const library = atom({ plugin: 'deskfit', key: 'library' } as const, { region: 'all', place: 'all', isMine: false, shown: 4 } as Library)

/** Moves the person has passed on since the last set, so a shuffle never goes back to them. */
let passed: string[] = []

